function show(html){workspace.classList.remove('hidden');panel.innerHTML=html;workspace.scrollIntoView({behavior:'smooth',block:'start'})}
function setTheme(paper=false){document.body.dataset.theme=paper?'paper':'console'}
function selectMode(id,action){return()=>{setTheme(false);let items=[...document.querySelectorAll('.nav-item')],item=document.querySelector(`#${id}`),n=items.indexOf(item)+1;items.forEach(x=>x.classList.toggle('active',x===item));let title=item?.querySelector('b')?.textContent||'CashDrop';document.querySelector('.docbar>span').textContent=`CD-${String(n).padStart(2,'0')} · ${title.toUpperCase()}`;action()}}
function err(e){console.error(e);return esc(e?.message||e)}
function save(name,data){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const linkFor=x=>`${location.origin}${location.pathname}#/claim?${new URLSearchParams(x)}`;

function createDrop(){
 show(`<h2>Create a CashDrop</h2><p>A private digital envelope with an optional password, generated locally.</p><form id="drop-form"><label class="field"><span>Amount in testnet ZEC</span><input name="amount" type="number" min=".0002" step=".00000001" value=".01" required><small>Add 0.0001 ZEC for the claim fee.</small></label><label class="field"><span>Private note</span><textarea name="note" maxlength="120" rows="3"></textarea></label><label class="field"><span>Password (optional)</span><input name="password" type="password" minlength="6" autocomplete="new-password" placeholder="Share separately"><small>With a password, the key is not placed in the link.</small></label><label class="field"><span>Suggested claim deadline</span><input name="deadline" type="date"><small>A visible reminder, not an on-chain lock.</small></label><button class="primary">Generate private drop</button></form>`);
 document.querySelector('#drop-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget),amount=String(f.get('amount')),note=String(f.get('note')||''),password=String(f.get('password')||''),deadline=String(f.get('deadline')||'');try{show('<h2>Preparing your drop</h2><div class="status busy">Creating a fresh shielded address…</div>');let x=await identity(),gift={v:2,type:'drop',network:'test',seed:x.seed,birthday:x.birthday,amount,note,deadline,createdAt:new Date().toISOString()},link=linkFor(await encrypt(gift,password)),fund=toZec(toZat(amount)+FEE);show(`<h2>Fund, then share</h2><p>Send exactly <strong>${fund} testnet ZEC</strong> here:</p><div class="address">${esc(x.address)}</div><div class="row" style="margin-top:16px"><button class="secondary" id="copy-address">Copy address</button><button class="secondary" id="save-recovery">Save recovery</button></div><label class="field"><span>Private claim link</span><textarea id="claim-link" rows="5" readonly>${esc(link)}</textarea><small>${password?'Password protected. Send the password separately.':'Whoever has the complete link can claim first.'}</small></label><button class="primary" id="copy-link">Copy claim link</button><p class="notice">Save recovery before sharing. Testnet coins have no monetary value.</p>`);document.querySelector('#copy-address').onclick=()=>navigator.clipboard.writeText(x.address);document.querySelector('#copy-link').onclick=()=>navigator.clipboard.writeText(link);document.querySelector('#save-recovery').onclick=()=>save(`cashdrop-${x.birthday}-recovery.json`,{type:'CashDrop recovery',version:2,network:'test',address:x.address,link,amount,note,deadline,seed:x.seed,birthday:x.birthday,passwordProtected:!!password})}catch(error){show(`<h2>Could not create the drop</h2><p class="error">${err(error)}</p><button class="secondary" id="retry">Try again</button>`);document.querySelector('#retry').onclick=createDrop}}
}

function createBatch(){
 show('<h2>Create a DropBatch</h2><p>Separate private envelopes for a team, event, giveaway, or payroll run.</p><form id="batch-form"><label class="field"><span>Recipients</span><input name="count" type="number" min="2" max="20" value="3" required></label><label class="field"><span>Amount each (testnet ZEC)</span><input name="amount" type="number" min=".0002" step=".00000001" value=".01" required></label><label class="field"><span>Shared note</span><textarea name="note" maxlength="120" rows="2"></textarea></label><button class="primary">Create batch</button></form>');
 document.querySelector('#batch-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget),count=Number(f.get('count')),amount=String(f.get('amount')),note=String(f.get('note')||'');try{show(`<h2>Building DropBatch</h2><div class="status busy">Preparing ${count} independent wallets…</div><p>Every recipient gets a different seed.</p>`);let wallet=await freshWallet(),latest=Number(await wallet.get_latest_block()),birthday=Math.max(0,latest-10),drops=[];for(let i=0;i<count;i++){panel.querySelector('.status').textContent=`Creating envelope ${i+1} of ${count}…`;let seed=generate_seed_phrase(),id=await wallet.create_account(`Drop ${i+1}`,seed,0,birthday),address=await wallet.get_current_address(id),payload={v:2,type:'batch',batchIndex:i+1,network:'test',seed,birthday,amount,note,createdAt:new Date().toISOString()},link=linkFor(await encrypt(payload));drops.push({recipient:i+1,address,link,seed,birthday,amount,note})}let fund=toZec(toZat(amount)+FEE);show(`<h2>DropBatch ready</h2><p>Fund every address with <strong>${fund} testnet ZEC</strong>. Send each person only their matching link.</p><div class="bundle"><table><thead><tr><th>#</th><th>Funding address</th><th>Private link</th></tr></thead><tbody>${drops.map((d,i)=>`<tr><td>${i+1}</td><td><code>${esc(d.address.slice(0,20))}…</code></td><td><button class="secondary copy-batch" data-i="${i}">Copy link</button></td></tr>`).join('')}</tbody></table></div><button class="primary" id="save-batch">Download private batch bundle</button><p class="notice">The bundle contains all recovery seeds. Never send the whole bundle to recipients.</p>`);document.querySelectorAll('.copy-batch').forEach(b=>b.onclick=()=>navigator.clipboard.writeText(drops[Number(b.dataset.i)].link));document.querySelector('#save-batch').onclick=()=>save(`cashdrop-batch-${birthday}.json`,{type:'CashDrop DropBatch recovery',version:1,network:'test',fundEachZec:fund,drops})}catch(error){show(`<h2>Batch creation paused</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-batch">Try again</button>`);document.querySelector('#retry-batch').onclick=createBatch}}
}

function createFund(){
 show('<h2>Create a Private Fund</h2><p>Raise to one shielded address without publishing donors or their payments.</p><form id="fund-form"><label class="field"><span>Fund title</span><input name="title" maxlength="60" required></label><label class="field"><span>Goal in testnet ZEC</span><input name="goal" type="number" min=".0001" step=".00000001" value="1" required></label><label class="field"><span>Story</span><textarea name="description" maxlength="500" rows="4" required></textarea></label><label class="field"><span>Deadline (optional)</span><input name="deadline" type="date"></label><button class="primary">Create private fund</button></form>');
 document.querySelector('#fund-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget),campaign={v:1,network:'test',title:String(f.get('title')),goal:String(f.get('goal')),description:String(f.get('description')),deadline:String(f.get('deadline')||'')};try{show('<h2>Preparing fund</h2><div class="status busy">Creating the organizer wallet…</div>');let x=await identity('Private Fund'),publicCampaign={...campaign,address:x.address,createdAt:new Date().toISOString()},publicLink=`${location.origin}${location.pathname}#/fund?c=${b64(enc.encode(JSON.stringify(publicCampaign)))}`;show(`<h2>Your fund is live</h2><p>The public link has the shielded address, never the recovery seed.</p><label class="field"><span>Public fund link</span><textarea id="fund-link" rows="5" readonly>${esc(publicLink)}</textarea></label><div class="row"><button class="primary" id="copy-fund">Copy public link</button><button class="secondary" id="save-fund">Save organizer recovery</button></div><p class="notice">CashDrop does not expose donor identities, amounts, or a public balance. The organizer may disclose progress separately.</p>`);document.querySelector('#copy-fund').onclick=()=>navigator.clipboard.writeText(publicLink);document.querySelector('#save-fund').onclick=()=>save(`cashdrop-fund-${x.birthday}-recovery.json`,{type:'CashDrop Private Fund recovery',version:1,network:'test',campaign:publicCampaign,publicLink,seed:x.seed,birthday:x.birthday})}catch(error){show(`<h2>Fund creation paused</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-fund">Try again</button>`);document.querySelector('#retry-fund').onclick=createFund}}
}
function openFund(){setTheme(true);try{let p=new URLSearchParams(location.hash.split('?')[1]||''),c=JSON.parse(dec.decode(unb64(p.get('c')||'')));if(c.network!=='test'||!c.address?.startsWith('utest1'))throw Error('This fund link is incomplete or not for testnet.');show(`<div class="campaign"><span class="eyebrow">PRIVATE FUND · TESTNET</span><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><div class="amount">Goal: ${esc(c.goal)} <span style="color:var(--acc)">ZEC</span></div>${c.deadline?`<p><strong>Deadline:</strong> ${esc(c.deadline)}</p>`:''}<label class="field"><span>Shielded contribution address</span><textarea id="fund-address" rows="4" readonly>${esc(c.address)}</textarea></label><button class="primary" id="copy-contribution">Copy address</button><p class="notice">Send only testnet ZEC. CashDrop publishes no donor list or inferred balance.</p></div>`);document.querySelector('#copy-contribution').onclick=()=>navigator.clipboard.writeText(c.address)}catch(error){show(`<h2>Invalid Private Fund</h2><p class="error">${err(error)}</p>`)}}

function createCheckout(){
 show('<h2>Create a CashDrop Checkout</h2><p>Turn any phone or tablet into a private Zcash point of sale.</p><form id="checkout-form"><label class="field"><span>Merchant or store</span><input name="merchant" maxlength="60" placeholder="Ada’s Coffee" required></label><label class="field"><span>Item or service</span><input name="item" maxlength="80" placeholder="Coffee and pastry" required></label><label class="field"><span>Price in testnet ZEC</span><input name="amount" type="number" min=".0001" step=".00000001" value=".01" required></label><label class="field"><span>Order reference (optional)</span><input name="reference" maxlength="40" placeholder="ORDER-1042"></label><button class="primary">Create private checkout</button></form>');
 document.querySelector('#checkout-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget),checkout={v:1,type:'checkout',network:'test',merchant:String(f.get('merchant')),item:String(f.get('item')),amount:String(f.get('amount')),reference:String(f.get('reference')||''),createdAt:new Date().toISOString()};try{show('<h2>Preparing checkout</h2><div class="status busy">Creating a fresh merchant shielded address…</div>');let x=await identity('CashDrop Checkout'),publicCheckout={...checkout,address:x.address},publicLink=`${location.origin}${location.pathname}#/pay?c=${b64(enc.encode(JSON.stringify(publicCheckout)))}`;show(`<h2>Checkout ready</h2><p>Display or share this checkout link with the customer. The public page contains no merchant recovery seed.</p><label class="field"><span>Customer checkout link</span><textarea id="checkout-link" rows="5" readonly>${esc(publicLink)}</textarea></label><div class="row"><button class="primary" id="copy-checkout">Copy checkout link</button><button class="secondary" id="save-checkout">Save merchant recovery</button></div><p class="notice">Confirm payment in your merchant wallet before delivering the order. Opening the page is not proof of payment.</p>`);document.querySelector('#copy-checkout').onclick=()=>navigator.clipboard.writeText(publicLink);document.querySelector('#save-checkout').onclick=()=>save(`cashdrop-checkout-${x.birthday}-recovery.json`,{type:'CashDrop Checkout recovery',version:1,network:'test',checkout:publicCheckout,publicLink,seed:x.seed,birthday:x.birthday,amount:checkout.amount,note:`${checkout.merchant}: ${checkout.item}`})}catch(error){show(`<h2>Checkout creation paused</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-checkout">Try again</button>`);document.querySelector('#retry-checkout').onclick=createCheckout}}
}
function openCheckout(){setTheme(true);try{let p=new URLSearchParams(location.hash.split('?')[1]||''),c=JSON.parse(dec.decode(unb64(p.get('c')||'')));if(c.type!=='checkout'||c.network!=='test'||!c.address?.startsWith('utest1'))throw Error('This checkout link is incomplete or not for testnet.');let paymentUri=`zcash:${c.address}?amount=${encodeURIComponent(c.amount)}`;show(`<div class="campaign"><span class="eyebrow">PRIVATE CHECKOUT · TESTNET</span><h2>${esc(c.merchant)}</h2><p>${esc(c.item)}${c.reference?` · <code>${esc(c.reference)}</code>`:''}</p><div class="amount">${esc(c.amount)} <span style="color:var(--acc)">ZEC</span></div><div id="checkout-qr" style="width:232px;min-height:232px;margin:22px auto;padding:12px;background:white;border-radius:16px"></div><label class="field"><span>Pay this shielded address</span><textarea id="checkout-address" rows="4" readonly>${esc(c.address)}</textarea></label><button class="primary" id="copy-payment">Copy payment address</button><p class="notice">Scan or send exactly ${esc(c.amount)} testnet ZEC. The merchant must verify confirmation in their wallet; this page never fakes a paid status.</p></div>`);if(globalThis.QRCode)new QRCode(document.querySelector('#checkout-qr'),{text:paymentUri,width:208,height:208,colorDark:'#201515',colorLight:'#fffefb',correctLevel:QRCode.CorrectLevel.M});document.querySelector('#copy-payment').onclick=()=>navigator.clipboard.writeText(c.address)}catch(error){show(`<h2>Invalid checkout</h2><p class="error">${err(error)}</p>`)}}

function verifyPayment(){
 show('<h2>Verify a private payment</h2><p>Open the merchant recovery file created with Checkout or Plans. CashDrop reconstructs the merchant wallet and scans Zcash testnet locally.</p><label class="field"><span>Merchant recovery file</span><input id="verification-file" type="file" accept="application/json,.json"></label><div class="privacy-proof"><span>FILE STAYS LOCAL</span><span>NO CASHDROP ACCOUNT</span><span>NO PUBLIC BALANCE</span></div><p class="notice">The recovery file contains spending authority. Use it only on a device you trust and never send it to a customer.</p>');
 document.querySelector('#verification-file').onchange=async e=>{let data;try{data=JSON.parse(await e.target.files[0].text());if(!['CashDrop Checkout recovery','CashDrop Plan recovery'].includes(data.type)||!data.seed||data.birthday===undefined)throw Error('Choose a CashDrop Checkout or Plan merchant recovery file.');await scanMerchantPayment(data)}catch(error){show(`<h2>Verification paused</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-verification">Choose another file</button>`);document.querySelector('#retry-verification').onclick=verifyPayment}}
}
async function scanMerchantPayment(data){
 let details=data.checkout||data.plan||{},expected=toZat(data.amount||details.amount),label=data.type==='CashDrop Plan recovery'?'subscription renewal':'checkout payment';
 show(`<h2>Checking ${esc(label)}</h2><div class="status busy">Loading the wallet engine…</div><p>The private recovery data remains in browser memory while compact blocks are scanned.</p>`);
 try{let wallet=await freshWallet(),id=await wallet.create_account('Merchant verification',data.seed,0,Number(data.birthday));panel.querySelector('.status').textContent='Scanning Zcash testnet for shielded payments…';await wallet.sync();panel.querySelector('.status').textContent='Reading confirmed transaction history locally…';let history=await wallet.get_transaction_history(id,100,0),transactions=Array.from(history.transactions||[]).map(tx=>tx.toJSON?tx.toJSON():tx),received=transactions.filter(tx=>Number(tx.tx_type)===0).sort((a,b)=>Number(b.block_height||0)-Number(a.block_height||0)),matches=received.filter(tx=>BigInt(tx.value)>=expected),confirmed=matches.filter(tx=>Number(tx.status)===0&&Number(tx.confirmations)>0),pending=matches.filter(tx=>Number(tx.status)===1||Number(tx.confirmations)===0),underpaid=received.filter(tx=>BigInt(tx.value)>0n&&BigInt(tx.value)<expected);renderVerification(data,{expected,received,confirmed,pending,underpaid})}catch(error){show(`<h2>Could not verify yet</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-scan">Scan again</button><p class="notice">A network or gateway error is not proof of non-payment. Retry before fulfilling or rejecting an order.</p>`);document.querySelector('#retry-scan').onclick=()=>scanMerchantPayment(data)}
}
function renderVerification(data,result){
 let details=data.checkout||data.plan||{},isPlan=data.type==='CashDrop Plan recovery',title=isPlan?details.name:`${details.merchant||'Checkout'} · ${details.item||''}`,state=result.confirmed.length?'CONFIRMED':result.pending.length?'PENDING':result.underpaid.length?'UNDERPAID':'NOT FOUND',good=state==='CONFIRMED',cards=[...result.confirmed,...result.pending,...result.underpaid].map(tx=>{let ok=Number(tx.status)===0&&Number(tx.confirmations)>0&&BigInt(tx.value)>=result.expected,pending=!ok&&BigInt(tx.value)>=result.expected;return`<article class="receipt ${ok?'confirmed':pending?'pending':''}"><div class="receipt-head"><b>${toZec(BigInt(tx.value))} ZEC</b><span class="badge ${ok?'good':'wait'}">${ok?'CONFIRMED':pending?'PENDING':'UNDERPAID'}</span></div><dl><dt>Confirmations</dt><dd>${esc(tx.confirmations||0)}</dd><dt>Shielded pool</dt><dd>${esc(tx.pool||'shielded')}</dd><dt>Transaction</dt><dd><code>${esc(tx.txid)}</code></dd>${tx.memo?`<dt>Private memo</dt><dd>${esc(tx.memo)}</dd>`:''}</dl></article>`}).join('');
 show(`<span class="eyebrow">LOCAL MERCHANT VERIFICATION · TESTNET</span><h2>${esc(title)}</h2><div class="amount" style="color:${good?'#9bd27b':state==='NOT FOUND'?'var(--mute)':'var(--acc)'}">${state}</div><p>Expected: <strong>${toZec(result.expected)} ZEC</strong>${details.reference?` · Order <code>${esc(details.reference)}</code>`:''}</p>${cards?`<div class="verification">${cards}</div>`:'<p class="notice">No incoming shielded transaction was found for this merchant wallet. This is not proof that a customer intended to pay.</p>'}<div class="row"><button class="primary" id="scan-again">Scan again</button><button class="secondary" id="verify-another">Verify another</button></div><p class="privacy-line">Result computed on this device · recovery seed not uploaded · no public customer record</p>`);document.querySelector('#scan-again').onclick=()=>scanMerchantPayment(data);document.querySelector('#verify-another').onclick=verifyPayment
}

function createPlan(){
 show('<h2>Create a CashDrop Plan</h2><p>Offer a private recurring service where the customer approves every renewal.</p><form id="plan-form"><label class="field"><span>Plan name</span><input name="name" maxlength="60" placeholder="Private Supporter" required></label><label class="field"><span>Price in testnet ZEC</span><input name="amount" type="number" min=".0001" step=".00000001" value=".05" required></label><label class="field"><span>Billing period</span><select name="period"><option value="week">Weekly</option><option value="month" selected>Monthly</option><option value="year">Yearly</option></select></label><label class="field"><span>What the customer receives</span><textarea name="description" maxlength="300" rows="3" placeholder="Access to the private creator community" required></textarea></label><button class="primary">Create subscription plan</button></form>');
 document.querySelector('#plan-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget),plan={v:1,type:'plan',network:'test',name:String(f.get('name')),amount:String(f.get('amount')),period:String(f.get('period')),description:String(f.get('description')),createdAt:new Date().toISOString()};try{show('<h2>Preparing plan</h2><div class="status busy">Creating the plan’s shielded merchant address…</div>');let x=await identity('CashDrop Plan'),publicPlan={...plan,address:x.address},publicLink=`${location.origin}${location.pathname}#/plan?p=${b64(enc.encode(JSON.stringify(publicPlan)))}`;show(`<h2>Subscription plan ready</h2><p>Share this renewal page with customers. It cannot debit a wallet automatically.</p><label class="field"><span>Customer plan link</span><textarea id="plan-link" rows="5" readonly>${esc(publicLink)}</textarea></label><div class="row"><button class="primary" id="copy-plan">Copy plan link</button><button class="secondary" id="save-plan">Save merchant recovery</button></div><p class="notice">Each renewal is customer-approved. CashDrop never stores wallet authority or claims automatic recurring debits.</p>`);document.querySelector('#copy-plan').onclick=()=>navigator.clipboard.writeText(publicLink);document.querySelector('#save-plan').onclick=()=>save(`cashdrop-plan-${x.birthday}-recovery.json`,{type:'CashDrop Plan recovery',version:1,network:'test',plan:publicPlan,publicLink,seed:x.seed,birthday:x.birthday,amount:plan.amount,note:plan.name})}catch(error){show(`<h2>Plan creation paused</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-plan">Try again</button>`);document.querySelector('#retry-plan').onclick=createPlan}}
}
function openPlan(){setTheme(true);try{let p=new URLSearchParams(location.hash.split('?')[1]||''),c=JSON.parse(dec.decode(unb64(p.get('p')||'')));if(c.type!=='plan'||c.network!=='test'||!c.address?.startsWith('utest1'))throw Error('This subscription link is incomplete or not for testnet.');let period={week:'week',month:'month',year:'year'}[c.period]||'period';show(`<div class="campaign"><span class="eyebrow">PRIVATE SUBSCRIPTION · TESTNET</span><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><div class="amount">${esc(c.amount)} <span style="color:var(--acc)">ZEC / ${esc(period)}</span></div><label class="field"><span>Shielded renewal address</span><textarea id="plan-address" rows="4" readonly>${esc(c.address)}</textarea></label><button class="primary" id="copy-renewal">Copy renewal address</button><p class="notice">This is a customer-approved renewal, not an automatic debit. Send only when you want to renew and keep your payment receipt.</p></div>`);document.querySelector('#copy-renewal').onclick=()=>navigator.clipboard.writeText(c.address)}catch(error){show(`<h2>Invalid subscription plan</h2><p class="error">${err(error)}</p>`)}}

async function openClaim(){setTheme(true);let p=Object.fromEntries(new URLSearchParams(location.hash.split('?')[1]||''));if(!p.d||!p.n||(!p.k&&p.l!=='1'))return show('<span class="eyebrow">INVALID LINK</span><h2>This link is <em>incomplete.</em></h2><p class="error">Ask the sender for the complete CashDrop link.</p>');if(p.l==='1'){show('<span class="eyebrow">SEALED FOR YOU</span><h2>Unlock your <em>CashDrop.</em></h2><p>The password was not stored in the link.</p><form id="unlock-form"><label class="field"><span>Password</span><input name="password" type="password" autocomplete="current-password" required autofocus></label><button class="primary">Open privately →</button></form>');document.querySelector('#unlock-form').onsubmit=async e=>{e.preventDefault();try{await renderClaim(await decrypt(p,String(new FormData(e.currentTarget).get('password'))))}catch{panel.querySelector('.error')?.remove();panel.insertAdjacentHTML('beforeend','<p class="error">That password could not open this CashDrop.</p>')}};return}try{await renderClaim(await decrypt(p))}catch(error){show(`<h2>Invalid CashDrop</h2><p class="error">${err(error)}</p>`)}}
async function renderClaim(gift,title='Money is waiting for you.'){if(gift.network!=='test')throw Error('This drop is not for testnet.');let expired=gift.deadline&&new Date(gift.deadline+'T23:59:59')<new Date();show(`<span class="eyebrow">SOMEONE SENT YOU A CASHDROP</span><h2>${esc(title)}</h2><div class="amount">${esc(gift.amount||'Available balance')} <span style="color:var(--acc)">ZEC</span></div>${gift.note?`<p>“${esc(gift.note)}”</p>`:''}${expired?'<p class="error">The suggested deadline passed; the sender may have reclaimed this.</p>':''}<p>Enter a shielded testnet address. The browser scans, proves, and sweeps locally.</p><label class="field"><span>Your shielded testnet address</span><textarea id="destination" rows="4" placeholder="utest1…"></textarea></label><div class="row"><button class="primary" id="claim">Claim privately →</button><button class="secondary" id="new-wallet">I don’t have a wallet yet</button></div><p class="notice">Anyone with the complete unlocked link can claim first.</p>`);let saved=sessionStorage.getItem('cashdrop-new-address');if(saved){document.querySelector('#destination').value=saved;sessionStorage.removeItem('cashdrop-new-address')}document.querySelector('#new-wallet').onclick=()=>{sessionStorage.setItem('cashdrop-return-link',location.href);createWallet(true)};document.querySelector('#claim').onclick=()=>claimGift(gift,document.querySelector('#destination').value.trim())}
async function claimGift(gift,destination){if(!(destination.startsWith('utest1')||destination.startsWith('ztestsapling1')))return alert('Enter a shielded Zcash testnet address.');try{show('<h2>Opening the envelope</h2><div class="status busy">Loading the wallet engine…</div><p>Keep this tab open while compact blocks are scanned.</p>');let wallet=await freshWallet(),id=await wallet.create_account('Claim',gift.seed,0,Number(gift.birthday));panel.querySelector('.status').textContent='Scanning Zcash testnet…';await wallet.sync();let summary=await wallet.get_wallet_summary(),balances=summary?.account_balances,entries=Array.isArray(balances)?balances:Array.from(balances?.entries?.()||[]),account=entries.find(([x])=>Number(x)===Number(id)),pool=account?.[1]||{},spendable=BigInt(pool.sapling_balance?.spendable_value??pool.orchard_balance?.spendable_value??0);if(spendable<=FEE)throw Error('No spendable funds found. The drop may be unconfirmed, unfunded, or claimed.');panel.querySelector('.status').textContent='Generating the zero-knowledge proof locally…';let proposal=await wallet.propose_transfer(id,destination,spendable-FEE),txids=await wallet.create_proposed_transactions(proposal,gift.seed,0);panel.querySelector('.status').textContent='Broadcasting…';await wallet.send_authorized_transactions(txids);show(`<h2>CashDrop claimed</h2><div class="amount">${toZec(spendable-FEE)} ZEC</div><p>Accepted for broadcast.</p>`);history.replaceState(null,'',location.pathname)}catch(error){show(`<h2>Claim paused</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-claim">Try again</button>`);document.querySelector('#retry-claim').onclick=()=>renderClaim(gift)}}

function recover(){show('<h2>Recover or reclaim</h2><p>Open a recovery JSON from a drop, batch, or fund.</p><label class="field"><span>Recovery file</span><input id="recovery-file" type="file" accept="application/json,.json"></label><p class="notice">The file stays in this browser.</p>');document.querySelector('#recovery-file').onchange=async e=>{try{let data=JSON.parse(await e.target.files[0].text());if(data.type==='CashDrop DropBatch recovery'){show(`<h2>Choose an envelope</h2><div class="bundle">${data.drops.map((d,i)=>`<button class="secondary recover-batch" data-i="${i}">Reclaim ${i+1}</button>`).join(' ')}</div>`);document.querySelectorAll('.recover-batch').forEach(b=>b.onclick=()=>renderClaim(data.drops[Number(b.dataset.i)],'Reclaim this envelope'));return}if(!data.seed||data.birthday===undefined)throw Error('Unsupported recovery file.');await renderClaim({network:'test',seed:data.seed,birthday:data.birthday,amount:data.amount||data.campaign?.goal||'Available balance',note:data.note||data.campaign?.title||''},'Reclaim your funds')}catch(error){show(`<h2>Could not open recovery</h2><p class="error">${err(error)}</p><button class="secondary" id="retry-recovery">Try another</button>`);document.querySelector('#retry-recovery').onclick=recover}}}
async function createWallet(returning=false){try{show('<h2>Your testnet wallet</h2><div class="status busy">Generating locally…</div>');let x=await identity('Browser wallet');show(`<h2>Back up your wallet</h2><label class="field"><span>Shielded testnet address</span><textarea id="wallet-address" rows="4" readonly>${esc(x.address)}</textarea></label><label class="field"><span>24-word recovery phrase</span><div class="secret">${esc(x.seed)}</div><small>Never share these words.</small></label><label class="field"><span><input id="backed-up" type="checkbox"> I saved the phrase privately</span></label><div class="row"><button class="secondary" id="copy-wallet">Copy address</button>${returning?'<button class="primary" id="return-claim" disabled>Return to claim</button>':''}</div>`);document.querySelector('#copy-wallet').onclick=()=>navigator.clipboard.writeText(x.address);let check=document.querySelector('#backed-up'),back=document.querySelector('#return-claim');if(back){check.onchange=()=>back.disabled=!check.checked;back.onclick=()=>{let link=sessionStorage.getItem('cashdrop-return-link');sessionStorage.setItem('cashdrop-new-address',x.address);sessionStorage.removeItem('cashdrop-return-link');location.href=link}}}catch(error){show(`<h2>Wallet unavailable</h2><p class="error">${err(error)}</p>`)}}

document.querySelector('#start-create').onclick=selectMode('start-create',createDrop);document.querySelector('#start-batch').onclick=selectMode('start-batch',createBatch);document.querySelector('#start-checkout').onclick=selectMode('start-checkout',createCheckout);document.querySelector('#start-verify').onclick=selectMode('start-verify',verifyPayment);document.querySelector('#start-plan').onclick=selectMode('start-plan',createPlan);document.querySelector('#start-fund').onclick=selectMode('start-fund',createFund);document.querySelector('#start-recover').onclick=selectMode('start-recover',recover);document.querySelector('#start-wallet').onclick=selectMode('start-wallet',()=>createWallet());document.querySelector('#welcome-create').onclick=selectMode('start-create',createDrop);

function setMobileTab(name){document.querySelectorAll('.mobile-tabs button').forEach(button=>button.classList.toggle('active',button.dataset.mobileScreen===name||(name==='send'&&button.dataset.mobileAction==='start-create')))}
function mobileHub(name){setTheme(false);setMobileTab(name);let hubs={merchant:`<span class="eyebrow">MERCHANT TOOLS · TESTNET</span><h2>Accept shielded payments.</h2><p>Take a private point-of-sale payment, offer customer-approved renewals, or verify an incoming payment locally.</p><div class="mobile-action-list"><button data-go="start-checkout"><b>Private Checkout</b><span>Create a payment page and QR code</span></button><button data-go="start-plan"><b>Subscription Plans</b><span>Private, customer-approved renewals</span></button><button data-go="start-verify"><b>Verify Payment</b><span>Scan testnet from a merchant recovery file</span></button></div>`,inbox:`<span class="eyebrow">PRIVATE INBOX</span><h2>Open money from its link.</h2><p>CashDrop does not keep a central inbox or learn who paid whom. Open the private link the sender shared with you to claim an envelope.</p><div class="mobile-action-list"><button data-go="start-wallet"><b>Create a wallet</b><span>Get a shielded testnet address on this device</span></button><button data-go="start-recover"><b>Recover funds</b><span>Open a saved CashDrop recovery file</span></button></div><p class="notice">Your claim links and wallet secrets are not stored by CashDrop.</p>`,more:`<span class="eyebrow">MORE CASHDROP</span><h2>Private money, more ways.</h2><div class="mobile-action-list"><button data-go="start-batch"><b>DropBatch</b><span>Prepare private envelopes for a group</span></button><button data-go="start-fund"><b>Private Fund</b><span>Raise without publishing a donor graph</span></button><button data-go="start-recover"><b>Recover or reclaim</b><span>Use your private recovery file</span></button><button data-go="start-wallet"><b>Browser wallet</b><span>Create a testnet wallet locally</span></button></div>`};show(hubs[name]);document.querySelector('.docbar>span').textContent=name.toUpperCase();document.querySelectorAll('[data-go]').forEach(button=>button.onclick=()=>document.querySelector(`#${button.dataset.go}`).click())}

document.querySelector('#mobile-create-hero').onclick=()=>{setMobileTab('send');document.querySelector('#start-create').click()};document.querySelectorAll('[data-mobile-action]').forEach(button=>button.onclick=()=>{setMobileTab('send');document.querySelector(`#${button.dataset.mobileAction}`).click()});document.querySelectorAll('[data-mobile-screen]').forEach(button=>button.onclick=()=>mobileHub(button.dataset.mobileScreen));document.querySelector('#mobile-back').onclick=()=>{if(location.hash){history.back()}else{location.reload()}};

workspace.addEventListener('input',e=>{let amount=document.querySelector('#preview-amount'),note=document.querySelector('#preview-note'),stamp=document.querySelector('#preview-stamp');if(e.target.name==='amount'&&amount)amount.textContent=e.target.value||'0';if(e.target.name==='note'&&note)note.textContent=e.target.value||'your private note appears here';if(e.target.name==='password'&&stamp)stamp.textContent=e.target.value?'LOCKED':'UNSEALED'});function route(){if(location.hash.startsWith('#/claim?'))openClaim();else if(location.hash.startsWith('#/fund?'))openFund();else if(location.hash.startsWith('#/pay?'))openCheckout();else if(location.hash.startsWith('#/plan?'))openPlan();else setTheme(false)}route();addEventListener('hashchange',route);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.warn);
